          "task": "AV_desk",
          "duration": { "type": "fixed", "seconds": 1800 },
          "startTrigger": { "type": "programStart" },
          "metadata": { "sourceSpan": { "quote": "Line check at the AV desk: laptop, HDMI, house sound, record feed. 30 minutes.", "occurrence": 1 }, "inferred": false }
        },
        {
          "stepId": "projector-test",
          "name": "Test the projector",
